require('./test-six-archives-index.cjs');
const M=require('../src/models'),F=require('../src/modules/report/financialProfitController'),dates=require('../src/modules/report/commissionDates'),a=require('node:assert/strict'),fs=require('fs'),path=require('path');
(async()=>{const stores=await M.Store.findAll({where:{is_deleted:0,status:1},raw:true});const ids=stores.map(s=>s.store_id),f=await F.queryFinancialProfit({storeIds:ids,startDate:'2026-10-01',endDate:'2026-10-31',includeStores:true,salesStageOnly:true});
 const rows=await M.sequelize.query(`SELECT pa.ADJUSTMENT_ID id,pa.ADJUSTMENT_NO no,pa.SIGNED_AMOUNT amount,pa.STORE_ID storeId FROM T_PERFORMANCE_PROFIT_ADJUSTMENT pa WHERE pa.STATUS='approved' AND pa.STORE_ID IN (:ids) AND DATE(${dates.adjustmentSql('pa')}) BETWEEN '2026-10-01' AND '2026-10-31'`,{replacements:{ids},type:M.sequelize.QueryTypes.SELECT});
 const missing=rows.filter(r=>Number(r.amount)!==0&&!f.profitDetails.some(e=>e.eventKey==='performance:'+r.id));a.equal(missing.length,0,'已批准调整遗漏');
 for(const r of rows.filter(r=>Number(r.amount)!==0)){const e=f.profitDetails.find(e=>e.eventKey==='performance:'+r.id);if(!['D028000','D023000'].includes(r.storeId))a.equal(e.salesGrossProfit,Number(r.amount));}
 const results=stores.filter(s=>!['D028000','D023000'].includes(s.store_id)).map(s=>{const events=f.profitDetails.filter(e=>String(e.storeId)===String(s.store_id));const grouped={};for(const e of events){const g=grouped[e.entryType]||{count:0,sales:0};g.count++;g.sales=Math.round((g.sales+Number(e.salesGrossProfit))*100)/100;grouped[e.entryType]=g;}const total=Math.round(events.reduce((sum,e)=>sum+Number(e.salesGrossProfit),0)*100)/100;const summary=f.storeSummaries.find(r=>String(r.storeId)===String(s.store_id)).summary.salesGrossProfit;a.equal(total,summary);return {store:s.name,total,grouped};});
 const returns=await M.sequelize.query("SELECT RETURN_ID id,STORE_ID storeId,SUM(GROSS_PROFIT_AMOUNT) amount FROM T_SALES_RETURN_GROSS_PROFIT WHERE STORE_ID IN (:ids) AND CREATE_TIME >= '2026-10-01 00:00:00' AND CREATE_TIME < '2026-11-01 00:00:00' GROUP BY RETURN_ID,STORE_ID",{replacements:{ids},type:M.sequelize.QueryTypes.SELECT});
 for(const r of returns){const e=f.profitDetails.find(e=>e.eventKey==='return:'+r.id);a(e,'退货冻结流水遗漏');if(!['D028000','D023000'].includes(r.storeId))a.equal(e.salesGrossProfit,e.instantRetail?require('../src/modules/report/performanceAllocation').splitInstantRetail(Number(r.amount)).sales:Number(r.amount));}
 const out={approvedAdjustments:rows.length,postedReturns:returns.length,missing,stores:results};fs.writeFileSync(path.resolve(__dirname,'../backup/manager-threshold-20261112/events.json'),JSON.stringify(out,null,2));console.log(JSON.stringify({approvedAdjustments:rows.length,postedReturns:returns.length,missing}));})().catch(e=>{console.error(e.stack);process.exitCode=1}).finally(()=>M.sequelize.close());
